/**
 * Curated seed list of core AI/ML journals (generated by verifying each title against OpenAlex
 * and each ISSN's print/online type against Crossref; URLs were fetched before being listed).
 *
 * - ISSNs: exactly as OpenAlex/Crossref list them; `issnPrint`/`issnOnline` only when Crossref
 *   types them. DMLR has no ISSN yet (its site says the ISSN is pending).
 * - `openAccess` is set here only for journals whose own sites state free access with no author
 *   fees (OpenAlex under-reports some diamond-OA titles); everything else comes from OpenAlex.
 * - `apcUsd: 0` only for diamond-OA journals whose sites state no author fees.
 * - `scopeUrl`/`cfpUrl` are fetched politely at ingest (robots.txt, ≥1 req/s, cached). Publishers
 *   that block automated clients (ScienceDirect, ACM DL, MIT Press Direct) get no scope URL.
 */
import type { SubfieldId } from "@/lib/taxonomy";

export interface JournalSeed {
  slug: string;
  abbreviation: string;
  name: string;
  issnPrint: string | null;
  issnOnline: string | null;
  issns: string[];
  openalexId: string | null;
  publisher: string | null;
  homepage: string | null;
  scopeUrl: string | null;
  submissionUrl: string | null;
  /** Springer "updates" page listing calls for papers (special issues / collections). */
  cfpUrl: string | null;
  subfields: SubfieldId[];
  openAccess?: "full" | "hybrid" | "subscription";
  /** Set only where the journal's site states there are no author fees (diamond OA). */
  apcUsd?: number;
}

